INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a81d5fd2-36d5-59c9-a1f9-641b2c331431','13f09cf4-c587-5ccb-ae52-a54ed40eb6bc','The verb ''can''',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the verb 'can' to show ability. 'Can' is the same for all persons: I/you/he/she/it/we/they can. The negative long form is 'cannot' and the short form is 'can't'. To make questions, we put 'can' before the subject: Can I ...?"}, {"type": "rule", "text": "For short answers we say: Yes, I/you/he/she/it/we/they can. or No, I/you/he/she/it/we/they can't."}, {"type": "examples", "items": ["I can play the piano.", "She cannot swim.", "He can't dance.", "Can you jump? - Yes, I can.", "Can he ski? - No, he can't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('81d2dda0-b064-51f8-a213-0dfba56d879c','a81d5fd2-36d5-59c9-a1f9-641b2c331431',0,'CHOOSE','Выберите правильную форму глагола ''can''.',$j${"items": [{"before": "She", "after": "play the piano.", "options": [{"id": "o1", "label": "can"}, {"id": "o2", "label": "cans"}]}, {"before": "", "after": "you dance? - Yes, I can.", "options": [{"id": "o1", "label": "Can"}, {"id": "o2", "label": "Do"}]}, {"before": "He", "after": "swim. He is afraid of water.", "options": [{"id": "o1", "label": "can't"}, {"id": "o2", "label": "don't"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('81d2dda0-b064-51f8-a213-0dfba56d879c',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3a8089bc-348b-501f-af1a-6efde4168cf5','a81d5fd2-36d5-59c9-a1f9-641b2c331431',1,'FILL_BLANK','Дополните краткие ответы, используя форму глагола ''can''.',$j${"items": [{"before": "Can you swim? Yes, I", "after": "."}, {"before": "Can he dance? No, he", "after": "."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3a8089bc-348b-501f-af1a-6efde4168cf5',$j${"items": [{"accept": ["can"]}, {"accept": ["can't", "cannot"]}]}$j$::jsonb,'');
