INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('f7141093-bc0a-501e-8ab4-f9814d14904e','a0000000-0000-4000-8000-0000000000f4','Блок 14. Countable and Uncountable Nouns: much / many, some / any',14,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('70dbbe48-e017-5894-a5e4-dd697019df58','f7141093-bc0a-501e-8ab4-f9814d14904e','Countable and Uncountable Nouns: much / many, some / any',0,'LESSON',70,$j$[{"type": "rule", "text": "We use much with uncountable nouns (sugar, milk, salt) and many with countable nouns in the plural (limes, eggs, peppers). We use How much...? and How many...? to ask about quantity."}, {"type": "rule", "text": "We use some only in affirmative sentences with countable nouns in the plural and with uncountable nouns."}, {"type": "rule", "text": "We use any only in interrogative and negative sentences with countable nouns in the plural and with uncountable nouns."}, {"type": "examples", "items": ["There is some cheese. / There isn't any cheese. / Is there any cheese?", "There are some grapes. / There aren't any grapes. / Are there any grapes?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('eb1555dd-1422-56ae-9c28-ec89c5d3c1a5','70dbbe48-e017-5894-a5e4-dd697019df58',0,'CHOOSE','Прочитайте и обведите правильное слово (much или many).',$j${"items": [{"before": "How", "after": "sugar do we need?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "How", "after": "limes do you want me to buy?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "How", "after": "milk do you want in your tea?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "How", "after": "salt is in the food?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "How", "after": "green peppers do we need?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "How", "after": "eggs are in the fridge?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('eb1555dd-1422-56ae-9c28-ec89c5d3c1a5',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e0eb6d87-7cf6-5f8a-b45b-e9aba8bf5b93','70dbbe48-e017-5894-a5e4-dd697019df58',1,'FILL_BLANK','Вставьте some или any.',$j${"items": [{"before": "There isn't", "after": "cheese."}, {"before": "They've got", "after": "coconuts."}, {"before": "They haven't got", "after": "coconuts."}, {"before": "Does she need", "after": "olive oil?"}, {"before": "She needs", "after": "olive oil."}, {"before": "Are there", "after": "grapes?"}, {"before": "There aren't", "after": "grapes."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e0eb6d87-7cf6-5f8a-b45b-e9aba8bf5b93',$j${"items": [{"accept": ["any"]}, {"accept": ["some"]}, {"accept": ["any"]}, {"accept": ["any"]}, {"accept": ["some"]}, {"accept": ["any"]}, {"accept": ["any"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('216ed5ad-7e81-5860-b4b2-302f8d760ede','a0000000-0000-4000-8000-0000000000f4','Блок 15. Comparative and Superlative Forms',15,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('70e4e621-8609-5e79-bb25-d6565a13da69','216ed5ad-7e81-5860-b4b2-302f8d760ede','Comparative and Superlative Forms',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the comparative form to compare two people or things. To form the comparative we add -er to the adjective and then use than. Structure: adjective + -er + than."}, {"type": "rule", "text": "We use the superlative form to compare a person or thing with two or more people or things. To form the superlative we use the word the, add -est to the adjective and then of/in. Structure: the + adjective + -est + of/in."}, {"type": "rule", "text": "Spelling rules: adjectives ending in -e take -st (large - largest); adjectives ending in a single stressed vowel followed by a consonant double the last consonant (fat - fattest); adjectives ending in a consonant + y drop the -y and take -iest (happy - happiest)."}, {"type": "examples", "items": ["The cheetah is faster than the lion.", "The cheetah is the fastest animal in the world.", "good - better - the best", "bad - worse - the worst"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('30cf98eb-9e1b-5615-a07a-cab8223b4598','70e4e621-8609-5e79-bb25-d6565a13da69',0,'FILL_BLANK','Напишите сравнительную форму прилагательного (comparative).',$j${"items": [{"before": "large →", "after": ""}, {"before": "fat →", "after": ""}, {"before": "happy →", "after": ""}, {"before": "fast →", "after": ""}, {"before": "slow →", "after": ""}, {"before": "good →", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('30cf98eb-9e1b-5615-a07a-cab8223b4598',$j${"items": [{"accept": ["larger"]}, {"accept": ["fatter"]}, {"accept": ["happier"]}, {"accept": ["faster"]}, {"accept": ["slower"]}, {"accept": ["better"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d7004c97-73b4-5742-a37c-d4d1e724a707','70e4e621-8609-5e79-bb25-d6565a13da69',1,'FILL_BLANK','Напишите превосходную форму прилагательного (superlative) без the.',$j${"items": [{"before": "large → the", "after": ""}, {"before": "big → the", "after": ""}, {"before": "happy → the", "after": ""}, {"before": "fast → the", "after": ""}, {"before": "good → the", "after": ""}, {"before": "bad → the", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('d7004c97-73b4-5742-a37c-d4d1e724a707',$j${"items": [{"accept": ["largest"]}, {"accept": ["biggest"]}, {"accept": ["happiest"]}, {"accept": ["fastest"]}, {"accept": ["best"]}, {"accept": ["worst"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e40fa4c8-1089-5dd8-a7b0-a8679826f6ba','a0000000-0000-4000-8000-0000000000f4','Блок 16. Past Simple: was / were',16,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('faf6450b-95c8-5408-9335-61ef971050b7','e40fa4c8-1089-5dd8-a7b0-a8679826f6ba','Past Simple: was / were',0,'LESSON',70,$j$[{"type": "rule", "text": "Was and were are the past simple forms of the verb to be. We use was with I, he, she and it. We use were with you, we and they."}, {"type": "rule", "text": "The negative forms are wasn't (was not) and weren't (were not). In questions was/were come before the subject: Was he at school? Were they at home?"}, {"type": "examples", "items": ["Were you at the funfair yesterday? No, I wasn't.", "Was he at the museum yesterday? Yes, he was.", "They were at home last night.", "She wasn't at the theatre yesterday."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e1756460-490c-5769-b2f3-ae6a57dc1fcd','faf6450b-95c8-5408-9335-61ef971050b7',0,'FILL_BLANK','Вставьте was или were.',$j${"items": [{"before": "", "after": "he at the theatre yesterday?"}, {"before": "", "after": "they at the funfair yesterday?"}, {"before": "", "after": "she at the museum yesterday?"}, {"before": "I", "after": "at home yesterday."}, {"before": "You", "after": "at school yesterday."}, {"before": "We", "after": "at the park yesterday."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e1756460-490c-5769-b2f3-ae6a57dc1fcd',$j${"items": [{"accept": ["Was"]}, {"accept": ["Were"]}, {"accept": ["Was"]}, {"accept": ["was"]}, {"accept": ["were"]}, {"accept": ["were"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a287ce7b-8631-5732-9b78-5ce91f286f76','faf6450b-95c8-5408-9335-61ef971050b7',1,'FILL_BLANK','Дайте краткий ответ (was, were, wasn''t или weren''t).',$j${"items": [{"before": "Was he at the tower yesterday? Yes,", "after": "."}, {"before": "Were they at the house yesterday? Yes,", "after": "."}, {"before": "Was she at the theatre yesterday? No,", "after": "."}, {"before": "Was he at the building yesterday? No,", "after": "."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('a287ce7b-8631-5732-9b78-5ce91f286f76',$j${"items": [{"accept": ["he was"]}, {"accept": ["they were"]}, {"accept": ["she wasn't", "she was not"]}, {"accept": ["he wasn't", "he was not"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('b7b3b14b-19c4-5a35-8aea-8b9dc1625f16','a0000000-0000-4000-8000-0000000000f4','Блок 17. A Story about Potatoes',17,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b0601355-9fea-50a3-b929-3490de09ccbd','b7b3b14b-19c4-5a35-8aea-8b9dc1625f16','A Story about Potatoes',0,'LESSON',70,$j$[{"type": "text", "text": "Sir Walter Raleigh was the first man to bring potatoes to the UK. He was a famous sailor and worked for Queen Elizabeth I. He sailed to America and carried the potatoes back with him. His servants planted the potatoes on his farm in Ireland."}, {"type": "text", "text": "Sir Walter offered the potatoes to the Queen as a gift. She invited everyone to a feast at her palace to taste the potatoes. The cooks were not sure what to do with the potatoes. They decided to cook the leaves and throw the potatoes into the bin! Everyone at the feast was very ill! These days, everyone in the UK eats potatoes - the right way!"}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8cffbc36-b451-5a1c-bb3d-e47633142bf0','b0601355-9fea-50a3-b929-3490de09ccbd',0,'SHORT_TEXT','Прочитай текст и ответь на вопрос (не более трёх слов).',$j${"question": "What was Sir Walter Raleigh?"}$j$::jsonb,10);
