INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('a6a2fc18-e53d-52dd-b901-57a4f85435ee','ee35db34-a89d-5d09-b4ed-6906150621d6','Going to: Future Plans',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'be going to' + verb to talk about future plans and intentions. Form: subject + am / is / are + going to + verb. Questions: Am / Is / Are + subject + going to + verb? Short answers: Yes, I am. / No, she isn't. / Yes, they are."}, {"type": "examples", "items": ["I am going to swim with the dolphins.", "She is going to buy a wetsuit.", "Are they going to go sailing?"]}, {"type": "text", "text": "Tim is a student. He studies hard every day. At the weekend he works at a cafe and goes to the cinema with his friends. But next week he is going to go on holiday to Greece with his friends."}]$j$::jsonb);
